import{_ as r,l as s,o as e,c as i,v as t,p as d,x as o,d as f,i as c,S as n}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"shuffle 与 broadcast join","description":"","frontmatter":{"title":"shuffle 与 broadcast join","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/distributed-join-shuffle.md","filePath":"cs/distributed-join-shuffle.md","lastUpdated":1789023840000}'),h={name:"cs/distributed-join-shuffle.md"};function u(p,a,b,E,_,A){const l=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="shuffle-与-broadcast-join" tabindex="-1">shuffle 与 broadcast join <a class="header-anchor" href="#shuffle-与-broadcast-join" aria-label="Permalink to &quot;shuffle 与 broadcast join&quot;">​</a></h1><div class="epigraph"><p>等值连接在分片上要让同键碰面：shuffle 按键重分区，broadcast 把小侧复制到每一片。网络字节是代价模型的新项。</p><footer>—— 据 Graefe exchange；DeWitt 并行连接；分布式 Grace 同构</footer></div><p><a href="/cs/shard-key-rebalance">上一课</a>把行放在片上。本课不选用户 id。缺口是连接：若两表已按连接键同切（collocated），工人本地连，无网络。否则要 <a href="/cs/parallel-exchange">exchange</a> 的网络版：shuffle join 或 broadcast join。单机 Grace 的分区文件换成网络块。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>大对大：两边按连接键 hash 送到 \\(N\\) 个工人，正确性同 Grace。小对大：广播小表，大表本地扫，避免动大表。缺口是估计：小表估错会变成广播一张大表打爆内存——基数误差的分布式形态。倾斜：单键打到一工人，同单机倾斜。</p><p>半连接归约：先传键再拉匹配行，Bernstein-Chiu 思想，减 payload。延迟物化：只 shuffle 键+位置，载荷留在存储节点——存算分离后课。</p><p><span class="marginnote">并行数据库教科书连接。Spark shuffle 是同一算子在批处理引擎。本课数据库执行器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>优化器比较：colocated \\(\\lt\\) broadcast \\(\\lt\\) shuffle（通常）。强制提示可钉。bloom 过滤器随广播或 shuffle 前过滤。外连接：broadcast 方向受限（只能广播被保留侧的对面等），与外连接下推防火墙同类。</p>',9)),(e(),d(n,null,{default:o(()=>[c(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20COL%5B%22%E5%90%8C%E9%94%AE%E5%90%8C%E5%88%87%22%5D%20--%3E%20LOC%5B%22%E6%9C%AC%E5%9C%B0%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20SMALL%5B%22%E5%B0%8F%E8%A1%A8%22%5D%20--%3E%20BC%5B%22%E5%B9%BF%E6%92%AD%E5%88%B0%E5%90%84%E5%A4%A7%E8%A1%A8%E7%89%87%22%5D%0A%20%20BIG%5B%22%E4%B8%A4%E8%A1%A8%E9%83%BD%E5%A4%A7%22%5D%20--%3E%20SH%5B%22%E6%8C%89%E9%94%AE%20shuffle%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[f(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RTO 无关；这是查询时流量。计划回归：统计变化让昨日 colocated 今日 shuffle。网络校准必须进代价模型，否则 DP 以为哈希内存连接免费。bloom 随广播或 shuffle 前过滤，减 payload，思想同 LSM 布隆但走的是连接键。</p><p>事务：分布式连接一般读快照，写仍按分片事务。连接本身不提交两片写。外连接限制 broadcast 方向。倾斜使某一工人收到大部分键，并行名存实亡——要拆热键或加盐，与单机 Grace 相同病。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 Percolator 锁。也不把 MapReduce shuffle 当 SQL 连接的定义——后课 MR 是另一套。图遍历的多跳 shuffle 更重，图库课。</p><p>后课默认：跨片等值连接靠 colocated / broadcast / shuffle 三选。Percolator：在 Bigtable 上用锁表做跨行事务。</p><p>网络是第二磁盘。估错大小等于估错 I/O。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同切本地连；否则广播小表或按键 shuffle。</li><li>倾斜与估错会打爆单工人。</li><li>Percolator 下一课：宽列上的分布式事务。</li><li>出处：Graefe；DeWitt；Bernstein-Chiu 半连接。</li></ul>',9))])}const C=r(h,[["render",u]]);export{B as __pageData,C as default};
